def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    env = observation.get("environment_name", "")

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        w = observation.get("grid_width", 1) or 1
        h = observation.get("grid_height", 1) or 1
        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        target = max(corners, key=lambda c: dist(c, opp_pos))
        move = step_toward(self_pos, target)
        if move == [0, 0]:
            move = step_away(self_pos, opp_pos)
        return move

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or []
        )
        best = None
        best_score = None
        for item in targets:
            p = pos(item, None)
            if p is None:
                continue
            score = dist(self_pos, p)
            if best_score is None or score < best_score:
                best_score = score
                best = p
        if best is not None:
            return step_toward(self_pos, best)
        return step_away(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_cells") or []
    best = None
    best_score = None
    for item in resources:
        p = pos(item, None)
        if p is None:
            continue
        val = 1
        if isinstance(item, dict):
            val = item.get("value", item.get("amount", 1)) or 1
        score = dist(self_pos, p) - 0.25 * val
        if best_score is None or score < best_score:
            best_score = score
            best = p
    if best is not None:
        return step_toward(self_pos, best)

    return step_toward(self_pos, opp_pos)

